#!/usr/bin/env bash
set -euo pipefail
GSZ=/opt/gsz
A="$GSZ/lib/botapi.js"; B="$GSZ/routes/whatsapp.js"
TS=$(date +%Y%m%d-%H%M%S)
echo "==> step179: IPTV renewal engine (botapi.getSubscription + /account/order/:no/subscription)"
for F in "$A" "$B"; do cp "$F" "$F.bak-step179-$TS"; done
echo "    backups: *.bak-step179-$TS"
restore(){ echo "!! restoring"; for F in "$A" "$B"; do cp "$F.bak-step179-$TS" "$F" 2>/dev/null||true; done; }
trap 'restore' ERR
P=$(mktemp /tmp/p179.XXXXXX.js); echo "" | base64 -d > "$P"
echo "==> applying"; NODE_PATH="$GSZ/node_modules" node "$P" "$GSZ"
echo "==> validating"
NODE_PATH="$GSZ/node_modules" node --check "$A" && echo "    botapi.js ok"
NODE_PATH="$GSZ/node_modules" node --check "$B" && echo "    whatsapp.js ok"
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
CODE=000; for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || echo 000); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] || { echo "    homepage $CODE"; false; }
echo "    homepage 200: OK (after ${i}s)"
rm -f "$P"; trap - ERR
echo ""
echo "==> step179 OK  Renewal engine live. Next: step180 adds the renewal card to the order page."
